'use strict';

// MAIN //

/**
* Returns a list of 20 colors as RGB hexadecimal strings for use as a categorical scheme.
*
* @returns {Array<string>} list of colors
*
* @example
* var list = category20b();
* // returns [...]
*/
function category20b() {
	return [
		'#393b79',
		'#5254a3',
		'#6b6ecf',
		'#9c9ede',
		'#637939',
		'#8ca252',
		'#b5cf6b',
		'#cedb9c',
		'#8c6d31',
		'#bd9e39',
		'#e7ba52',
		'#e7cb94',
		'#843c39',
		'#ad494a',
		'#d6616b',
		'#e7969c',
		'#7b4173',
		'#a55194',
		'#ce6dbd',
		'#de9ed6'
	];
}


// EXPORTS //

module.exports = category20b;
